import type { Directory, User } from "./types.ts";

export function grantsFor(user: User, directory: Directory): Set<string> {
  const grants = new Set<string>();
  for (const start of user.roles) {
    const seen = new Set<string>();
    for (let name: string | undefined = start; name && !seen.has(name); name = directory[name]?.parent) {
      seen.add(name);
      for (const g of directory[name]?.grants ?? []) grants.add(g);
    }
  }
  return grants;
}

